scene.add(new THREE.AmbientLight(0xffffff, 0.72));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.8);
keyLight.position.set(2, 5, 6);
scene.add(keyLight);

function meshMat(color, opts = {}) {
  return new THREE.MeshPhongMaterial({
    color,
    transparent: opts.transparent ?? false,
    opacity: opts.opacity ?? 1,
    side: opts.side ?? THREE.DoubleSide,
    depthWrite: opts.depthWrite ?? true,
    depthTest: opts.depthTest ?? true,
    shininess: opts.shininess ?? 20
  });
}
function basicMat(color, opts = {}) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: opts.transparent ?? false,
    opacity: opts.opacity ?? 1,
    side: opts.side ?? THREE.DoubleSide,
    depthWrite: opts.depthWrite ?? false,
    depthTest: opts.depthTest ?? false
  });
}
function lineMat(color, opacity = 1) {
  return new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity, depthTest: false });
}
function addLine(points, mat, parent) {
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), mat);
  parent.add(line);
  return line;
}
function ellipsePoints(cx, cy, rx, ry, z = 0.18, n = 96) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const a = (i / n) * Math.PI * 2;
    pts.push(new THREE.Vector3(cx + rx * Math.cos(a), cy + ry * Math.sin(a), z));
  }
  return pts;
}
function mulberry32(seed) {
  return function () {
    seed |= 0; seed = seed + 0x6D2B79F5 | 0;
    let t = Math.imul(seed ^ seed >>> 15, 1 | seed);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
function flaskHalfWidth(y) {
  if (y < 0.2) return 0.88 + 0.17 * (y / 0.2);
  if (y < 1.55) return 1.05 - 0.26 * ((y - 0.2) / 1.35);
  if (y < 2.25) return 0.79 - 0.41 * ((y - 1.55) / 0.70);
  if (y < 3.05) return 0.38;
  return 0.52;
}
function makeGlassShape() {
  const s = new THREE.Shape();
  s.moveTo(-0.52, 3.17);
  s.lineTo(-0.52, 3.05);
  s.lineTo(-0.38, 2.92);
  s.lineTo(-0.38, 2.25);
  s.bezierCurveTo(-0.54, 2.10, -0.66, 1.74, -0.79, 1.38);
  s.bezierCurveTo(-0.90, 1.02, -1.00, 0.58, -1.06, 0.30);
  s.bezierCurveTo(-1.11, 0.06, -0.72, -0.08, 0.00, -0.08);
  s.bezierCurveTo(0.72, -0.08, 1.11, 0.06, 1.06, 0.30);
  s.bezierCurveTo(1.00, 0.58, 0.90, 1.02, 0.79, 1.38);
  s.bezierCurveTo(0.66, 1.74, 0.54, 2.10, 0.38, 2.25);
  s.lineTo(0.38, 2.92);
  s.lineTo(0.52, 3.05);
  s.lineTo(0.52, 3.17);
  s.lineTo(-0.52, 3.17);
  return s;
}
function makeCorkShape() {
  const s = new THREE.Shape();
  s.moveTo(-0.42, 2.76);
  s.lineTo(-0.48, 3.58);
  s.quadraticCurveTo(0, 3.73, 0.48, 3.58);
  s.lineTo(0.42, 2.76);
  s.quadraticCurveTo(0, 2.65, -0.42, 2.76);
  return s;
}
function makeTrailShape(len, width) {
  const s = new THREE.Shape();
  s.moveTo(len * 0.48, 0);
  s.bezierCurveTo(len * 0.10, width, -len * 0.40, width * 0.92, -len * 0.50, 0);
  s.bezierCurveTo(-len * 0.40, -width * 0.92, len * 0.10, -width, len * 0.48, 0);
  return s;
}

const glassFillMat = basicMat(0xd7e7ea, { transparent: true, opacity: 0.50 });
const glassHighlightMat = basicMat(0xffffff, { transparent: true, opacity: 0.22 });
const glassOutlineMat = lineMat(0x778286, 0.96);
const glassInnerMat = lineMat(0xa9b5b8, 0.72);
const corkMat = meshMat(0xad5a24, { shininess: 8 });
const corkDarkMat = basicMat(0x7c3f18, { transparent: true, opacity: 0.42 });
const particleGeom = new THREE.SphereGeometry(0.105, 24, 18);
const particleSolidMat = meshMat(0x75a72b, { shininess: 34 });
const particlePaleMat = meshMat(0xa8c977, { transparent: true, opacity: 0.55, shininess: 26 });
const particleDarkMat = meshMat(0x5f941f, { shininess: 34 });
const trailMatTemplate = basicMat(0xa5c86b, { transparent: true, opacity: 0.18 });

function makeFlask(name, x, type) {
  const g = new THREE.Group();
  g.position.x = x;
  scene.add(g);

  const glassShape = makeGlassShape();
  const glassMesh = new THREE.Mesh(new THREE.ShapeGeometry(glassShape, 32), glassFillMat.clone());
  glassMesh.position.z = 0.00;
  g.add(glassMesh);

  const outline = addLine(glassShape.getPoints(120).map(p => new THREE.Vector3(p.x, p.y, 0.20)), glassOutlineMat.clone(), g);
  addLine(ellipsePoints(0, 0.02, 0.88, 0.13, 0.21), glassOutlineMat.clone(), g);
  addLine(ellipsePoints(0, 0.31, 1.02, 0.18, 0.17), glassInnerMat.clone(), g);
  addLine(ellipsePoints(0, 2.98, 0.55, 0.09, 0.22), glassOutlineMat.clone(), g);
  addLine(ellipsePoints(0, 3.15, 0.53, 0.11, 0.23), glassOutlineMat.clone(), g);
  addLine([new THREE.Vector3(-0.38, 2.25, 0.22), new THREE.Vector3(-0.38, 3.05, 0.22)], glassOutlineMat.clone(), g);
  addLine([new THREE.Vector3(0.38, 2.25, 0.22), new THREE.Vector3(0.38, 3.05, 0.22)], glassOutlineMat.clone(), g);

  const hiShape = new THREE.Shape();
  hiShape.moveTo(-0.56, 0.23);
  hiShape.bezierCurveTo(-0.42, 0.92, -0.42, 1.84, -0.20, 2.35);
  hiShape.lineTo(-0.03, 2.35);
  hiShape.bezierCurveTo(-0.20, 1.70, -0.24, 0.74, -0.35, 0.18);
  hiShape.quadraticCurveTo(-0.46, 0.17, -0.56, 0.23);
  const hi = new THREE.Mesh(new THREE.ShapeGeometry(hiShape, 20), glassHighlightMat.clone());
  hi.position.z = 0.08;
  g.add(hi);

  const cork = new THREE.Mesh(new THREE.ShapeGeometry(makeCorkShape(), 24), corkMat.clone());
  cork.position.z = 0.06;
  g.add(cork);
  const corkShade = new THREE.Mesh(new THREE.ShapeGeometry(new THREE.Shape([
    new THREE.Vector2(0.05, 2.74), new THREE.Vector2(0.31, 2.76),
    new THREE.Vector2(0.36, 3.58), new THREE.Vector2(0.12, 3.63)
  ])), corkDarkMat.clone());
  corkShade.position.z = 0.09;
  g.add(corkShade);
  addLine(ellipsePoints(0, 3.58, 0.48, 0.10, 0.24), lineMat(0x222222, 0.95), g);
  addLine(ellipsePoints(0, 2.76, 0.42, 0.075, 0.18), lineMat(0x5d2e12, 0.65), g);
  addLine([new THREE.Vector3(-0.48, 3.58, 0.24), new THREE.Vector3(-0.42, 2.76, 0.24)], lineMat(0x222222, 0.85), g);
  addLine([new THREE.Vector3(0.48, 3.58, 0.24), new THREE.Vector3(0.42, 2.76, 0.24)], lineMat(0x222222, 0.85), g);

  registerInteractive(glassMesh, {
    title: `${name} flask`,
    tooltip: `${name}: particle arrangements in this phase`,
    body: `This flask shows the ${name.toLowerCase()} state. Entropy is compared by how many different particle arrangements are available.`
  });
  registerInteractive(outline, {
    title: `${name} flask`,
    tooltip: `${name}: same container`,
    body: "The three flasks are identical containers; the visible difference is the distribution of the same number of particles."
  });

  const particles = [];
  const trails = [];
  const rnd = mulberry32(type === "solid" ? 91 : type === "liquid" ? 184 : 377);

  if (type === "solid") {
    let idx = 0;
    for (let row = 0; row < 5; row++) {
      const cols = row === 4 ? 5 : 6;
      for (let col = 0; col < cols && idx < 30; col++, idx++) {
        const px = (col - (cols - 1) / 2) * 0.155 + (row % 2) * 0.035;
        const py = 0.34 + row * 0.145;
        const p = new THREE.Mesh(particleGeom, (idx % 4 === 0 ? particleDarkMat : particleSolidMat).clone());
        p.position.set(px, py, 0.14 + 0.015 * (idx % 3));
        p.scale.setScalar(1.04);
        g.add(p);
        particles.push(p);
      }
    }
  } else if (type === "liquid") {
    for (let i = 0; i < 30; i++) {
      let px, py;
      for (let guard = 0; guard < 40; guard++) {
        px = -0.82 + rnd() * 1.64;
        py = 0.18 + rnd() * 0.60;
        const rx = 0.96 * (1 - Math.max(0, py - 0.15) * 0.08);
        if ((px * px) / (rx * rx) + ((py - 0.25) * (py - 0.25)) / 0.50 < 1.3) break;
      }
      const mat = (i % 5 === 0 ? particlePaleMat : (i % 3 === 0 ? particleDarkMat : particleSolidMat)).clone();
      if (mat.transparent) mat.opacity = 0.48 + rnd() * 0.18;
      const p = new THREE.Mesh(particleGeom, mat);
      p.position.set(px, py, 0.11 + 0.04 * rnd());
      p.scale.setScalar(0.96 + rnd() * 0.16);
      g.add(p);
      particles.push(p);
    }
  } else {
    for (let i = 0; i < 30; i++) {
      const py = 0.28 + rnd() * 2.18;
      const hw = Math.max(0.18, flaskHalfWidth(py) - 0.20);
      const px = (rnd() * 2 - 1) * hw;
      const angle = -0.95 + rnd() * 1.90;
      const len = 0.38 + rnd() * 0.30;
      const tr = new THREE.Mesh(new THREE.ShapeGeometry(makeTrailShape(len, 0.065), 18), trailMatTemplate.clone());
      tr.position.set(px - Math.cos(angle) * len * 0.18, py - Math.sin(angle) * len * 0.18, 0.055);
      tr.rotation.z = angle;
      g.add(tr);
      trails.push(tr);

      const mat = (i % 4 === 0 ? particlePaleMat : (i % 3 === 0 ? particleDarkMat : particleSolidMat)).clone();
      if (mat.transparent) mat.opacity = 0.48 + rnd() * 0.20;
      const p = new THREE.Mesh(particleGeom, mat);
      p.position.set(px, py, 0.13 + 0.035 * rnd());
      p.scale.setScalar(0.88 + rnd() * 0.18);
      g.add(p);
      particles.push(p);
    }
  }

  for (const p of particles) {
    registerInteractive(p, {
      title: `${name} particle`,
      tooltip: "Same particle count; different arrangements",
      body: "The spheres represent particles. In the crystalline solid they are ordered, in the liquid they spread around the bottom, and in the gas they fill much more of the container."
    });
  }

  return { group: g, particles, trails, name, type };
}

const flasks = {
  solid: makeFlask("Crystalline solid", -3.55, "solid"),
  liquid: makeFlask("Liquid", 0, "liquid"),
  gas: makeFlask("Gas", 3.55, "gas")
};

function makeArrow(x0, x1, y, z, color = 0x000000, parent = scene) {
  const g = new THREE.Group();
  parent.add(g);
  const mat = lineMat(color, 1);
  addLine([new THREE.Vector3(x0, y, z), new THREE.Vector3(x1, y, z)], mat, g);
  const dir = Math.sign(x1 - x0) || 1;
  const s = new THREE.Shape();
  s.moveTo(x1, y);
  s.lineTo(x1 - dir * 0.24, y + 0.09);
  s.lineTo(x1 - dir * 0.24, y - 0.09);
  s.lineTo(x1, y);
  const head = new THREE.Mesh(new THREE.ShapeGeometry(s), basicMat(color));
  head.position.z = z + 0.01;
  g.add(head);
  return g;
}
function setGroupColor(group, color) {
  group.traverse(o => {
    if (o.material && o.material.color) o.material.color.setHex(color);
  });
}

const topArrow = makeArrow(-3.55, 3.55, 4.53, 0.26, 0x000000);
topArrow.scale.x = 1.08;
registerInteractive(topArrow, {
  title: "Increasing entropy",
