};
const transitionLabels = {
  slPlus: addLabel("&Delta;S &gt; 0", new THREE.Vector3(-1.87, 2.30, 0.30), { fontSize: "22px" }),
  slMinus: addLabel("&Delta;S &lt; 0", new THREE.Vector3(-1.87, 1.62, 0.30), { fontSize: "22px" }),
