const stepButtons = [0, 1, 2, 3].map(i => document.getElementById(`step${i}`));

let currentTemp = 20;
let animTimer = null;
let highlightTimer = null;
const originalScales = new Map();
for (const obj of [...flasks.solid.particles, ...flasks.liquid.particles, ...flasks.gas.particles]) {
  originalScales.set(obj, obj.scale.clone());
}

function phaseFromTemp(t) {
  if (t <= 32) return "Crystalline solid";
  if (t <= 66) return "Liquid";
  return "Gas";
}
function keyFromPhase(phase) {
  return phase === "Crystalline solid" ? "solid" : phase === "Liquid" ? "liquid" : "gas";
}
function clearHighlights() {
  Object.values(transitionArrows).forEach(g => setGroupColor(g, 0x000000));
  Object.values(transitionLabels).forEach(l => {
    l.div.style.color = "#111";
    l.div.style.fontWeight = "normal";
    l.div.style.background = "transparent";
  });
  Object.values(captionLabels).forEach(l => {
    l.div.style.color = "#111";
    l.div.style.fontWeight = "normal";
  });
  for (const [obj, sc] of originalScales.entries()) obj.scale.copy(sc);
}
function highlightTransition(key, color) {
  clearHighlights();
  setGroupColor(transitionArrows[key], color);
  transitionLabels[key].div.style.color = `#${color.toString(16).padStart(6, "0")}`;
  transitionLabels[key].div.style.fontWeight = "bold";
  transitionLabels[key].div.style.background = "rgba(255,243,160,0.80)";
  clearTimeout(highlightTimer);
  highlightTimer = setTimeout(() => {
    setGroupColor(transitionArrows[key], 0x000000);
    transitionLabels[key].div.style.color = "#111";
    transitionLabels[key].div.style.fontWeight = "normal";
    transitionLabels[key].div.style.background = "transparent";
  }, 1800);
}
function selectPhase(phase, opts = {}) {
  const key = keyFromPhase(phase);
  phaseButtons.forEach(b => b.classList.toggle("active", b.dataset.phase === phase));
  if (opts.visual) {
    Object.values(captionLabels).forEach(l => {
      l.div.style.color = "#111";
      l.div.style.fontWeight = "normal";
    });
    captionLabels[phase].div.style.color = "#0b4f8a";
    captionLabels[phase].div.style.fontWeight = "bold";
    for (const [obj, sc] of originalScales.entries()) obj.scale.copy(sc);
    for (const p of flasks[key].particles) p.scale.copy(originalScales.get(p)).multiplyScalar(1.16);
  }
}
function updateTemperature(t, opts = {}) {
  currentTemp = Math.max(0, Math.min(100, Number(t)));
  const phase = phaseFromTemp(currentTemp);
  tempInput.value = String(Math.round(currentTemp));
  tempReadout.textContent = String(Math.round(currentTemp));
  phaseReadout.textContent = `Region: ${phase}`;
  selectPhase(phase, { visual: opts.visual });
  if (opts.transition) highlightTransition(opts.transition, opts.transition.endsWith("Plus") ? 0xd48400 : 0x1976d2);
}

phaseButtons.forEach(btn => {
  btn.addEventListener("click", () => {
    if (animTimer) clearTimeout(animTimer);
    clearHighlights();
    const phase = btn.dataset.phase;
    const targetTemp = phase === "Crystalline solid" ? 20 : phase === "Liquid" ? 55 : 85;
    const oldPhase = phaseFromTemp(currentTemp);
    updateTemperature(targetTemp, { visual: true });
    if (oldPhase === "Crystalline solid" && phase === "Liquid") highlightTransition("slPlus", 0xd48400);
    else if (oldPhase === "Liquid" && phase === "Crystalline solid") highlightTransition("slMinus", 0x1976d2);
    else if (oldPhase === "Liquid" && phase === "Gas") highlightTransition("lgPlus", 0xd48400);
    else if (oldPhase === "Gas" && phase === "Liquid") highlightTransition("lgMinus", 0x1976d2);
    narration.textContent =
      phase === "Crystalline solid"
        ? "Crystalline solid: the opaque green spheres sit in a compact, ordered cluster, so the number of accessible arrangements is smallest."
        : phase === "Liquid"
          ? "Liquid: the spheres are still near the bottom but can exchange positions and flow, giving more arrangements than the crystal."
          : "Gas: the spheres occupy the whole flask and show motion streaks, representing the largest number of accessible arrangements.";
  });
});
tempInput.addEventListener("input", () => {
  if (animTimer) clearTimeout(animTimer);
  const old = phaseFromTemp(currentTemp);
  const nextT = Number(tempInput.value);
  const next = phaseFromTemp(nextT);
  updateTemperature(nextT, { visual: true });
  if (old !== next) {
    if (old === "Crystalline solid" && next === "Liquid") highlightTransition("slPlus", 0xd48400);
    if (old === "Liquid" && next === "Crystalline solid") highlightTransition("slMinus", 0x1976d2);
    if (old === "Liquid" && next === "Gas") highlightTransition("lgPlus", 0xd48400);
    if (old === "Gas" && next === "Liquid") highlightTransition("lgMinus", 0x1976d2);
  }
});

